style.css:
/* Solo Leveling Inspired Twitter Theme - Black and Midnight Blue */

/* Twitter Body */
body {
    background: linear-gradient(135deg, #000000, #191970) !important; /* Black to midnight blue */
    color: #d3d3d3 !important; /* Light gray text */
    font-family: "Arial Narrow", Arial, sans-serif !important; /* Sharp, Twitter-friendly font */
    font-weight: 700;
}

/* Main Timeline */
div[role="main"] > div > div {
    background: #191970 !important; /* Midnight blue for timeline */
    border-radius: 10px;
    box-shadow: 0 0 15px rgba(25, 25, 112, 0.3);
}

/* Header (Top Navigation) */
header[role="banner"] {
    background: #000000 !important; /* Black header */
    border-bottom: 2px solid #4169e1 !important; /* Royal blue border */
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.7);
}

/* Tweets */
article[role="article"] {
    background: #000000 !important; /* Black tweet background */
    border: none !important;
    border-radius: 8px;
    margin-bottom: 10px;
    box-shadow: 0 0 10px rgba(25, 25, 112, 0.2);
}

/* Tweet Text */
div[lang] {
    color: #b0c4de !important; /* Soft blue-gray for readability */
    font-size: 1em;
}

/* Links in Tweets and Profile */
a[href*="/"] {
    color: #4169e1 !important; /* Royal blue links */
    text-transform: uppercase;
    letter-spacing: 1px;
}

a[href*="/"]:hover {
    color: #87cefa !important; /* Light sky blue on hover */
    transition: color 0.3s ease;
}

/* Buttons (Tweet, Like, Retweet) */
button, div[role="button"] {
    background: #4169e1 !important; /* Royal blue */
    color: #000000 !important; /* Black text */
    border: none !important;
    border-radius: 20px !important; /* Twitter’s rounded button style */
    font-family: "Arial Narrow", Arial, sans-serif !important;
    font-weight: 700;
    transition: background 0.3s ease, box-shadow 0.3s ease;
}

button:hover, div[role="button"]:hover {
    background: #87cefa !important; /* Light sky blue */
    box-shadow: 0 0 10px rgba(65, 105, 225, 0.5);
}

/* Sidebar (Trends, Who to Follow) */
aside[role="complementary"] > div {
    background: #191970 !important; /* Midnight blue sidebar */
    border-radius: 10px;
    box-shadow: 0 0 15px rgba(25, 25, 112, 0.3);
}

/* Trend Links */
section[aria-labelledby] a {
    color: #87cefa !important; /* Light sky blue */
}

section[aria-labelledby] a:hover {
    color: #4169e1 !important; /* Royal blue */
}

/* Tweet Composer and Search Input */
textarea[role="textbox"], input[type="text"] {
    background: #000000 !important; /* Black input */
    color: #d3d3d3 !important;
    border: 1px solid #4169e1 !important; /* Royal blue border */
    border-radius: 5px;
    font-family: "Arial Narrow", Arial, sans-serif !important;
    font-weight: 700;
}

/* Tweet Button in Composer */
div[role="button"][data-testid="tweetButtonInline"] {
    background: #4169e1 !important;
    border-radius: 20px !important;
}

div[role="button"][data-testid="tweetButtonInline"]:hover {
    background: #87cefa !important;
}

/* Clear Twitter’s Default Backgrounds */
div[class*="css-"], span[class*="css-"] {
    background: transparent !important;
}

/* Responsive Tweaks for Twitter */
@media (max-width: 768px) {
    article[role="article"] {
        margin: 8px !important;
    }
    button, div[role="button"] {
        padding: 6px 12px !important;
    }
}
